mapper.select:
select distinct gm.id, u.username, u.usertype, u.windowsaccount,
u.displayname , u.nickname , u.namezhspell, u.namezhshortspell, u.givenname , u.middlename , u.familyname ,
u.gender,
u.authntype, u.mobile, u.email, u.workemail, u.workphonenumber,
u.employeenumber, u.division, u.costcenter, u.organization, u.departmentid, u.department, u.jobtitle, u.joblevel,
gm.createddate,
u.status from mxk_userinfo u, mxk_groups g, mxk_group_member gm where u.instid = #{instId} and g.instid = #{instId} and gm.instid = #{instId}
and gm.groupid = #{groupId} and g.id = #{groupId}
and g.groupname = #{groupName}
and u.username = #{username}
and u.displayname like concat('%',#{displayName},'%')
and gm.type in( 'USER','USER-DYNAMIC') and gm.groupid = g.id and gm.memberid = u.id

select distinct u.id, u.username, u.usertype, u.windowsaccount,
u.displayname , u.nickname , u.namezhspell, u.namezhshortspell, u.givenname , u.middlename , u.familyname ,
u.gender,
u.authntype, u.mobile, u.email, u.workemail, u.workphonenumber,
u.employeenumber, u.division, u.costcenter, u.organization, u.departmentid, u.department, u.jobtitle, u.joblevel,
u.createdby, u.createddate, u.modifiedby, u.modifieddate,
u.status from mxk_userinfo u where u.instid = #{instId} and u.id not in( select gm.memberid from mxk_groups g,mxk_group_member gm where g.instid = #{instId} and gm.instid = #{instId}
and gm.groupid = #{groupId} and g.id = #{groupId}
and g.groupname = #{groupName}
and gm.type in( 'USER','USER-DYNAMIC') and gm.groupid = g.id )
and u.username = #{username}
and u.displayname like concat('%',#{displayName},'%')

select gm.id,
       gm.groupid,
       g.groupname,
       g.category,
       gm.memberid,
       u.username,
       u.displayname,
       gm.type,
       gm.createddate
from mxk_group_member gm
join mxk_groups g on g.id = gm.groupid and g.instid = #{instId}
join mxk_userinfo u on u.id = gm.memberid and u.instid = #{instId}
where gm.instid = #{instId}

    and gm.groupid = #{groupId}


    and u.username = #{username}

order by g.groupname, u.username

select g.*
from mxk_groups g
where g.instid = #{instId}
  and not exists (
      select 1
      from mxk_group_member gm
      join mxk_userinfo u on u.id = gm.memberid and u.instid = #{instId}
      where gm.instid = #{instId}
        and gm.groupid = g.id

            and u.username = #{username}

  )

    and g.groupname like concat('%', #{groupName}, '%')

order by g.groupname

select distinct ig.* from mxk_groups ig, mxk_groups g, mxk_group_member gm where 1 = 1 and gm.groupid = g.id and gm.memberid = ig.id and gm.type = 'GROUP'
and gm.groupid = #{groupId} and g.id = #{groupId}
and g.groupname = #{groupName}

